import time

from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeManagerException


class SleepyLoopWorker(object):
    """Class designed for working in loop until condition specified is done"""

    def __init__(self, timeout, refresh_time=1):
        """

        :param timeout:
        :param refresh_time:
        """
        self.timeout = timeout
        self.refresh_time = refresh_time
        self.lambda_get_value = None
        self.lambda_is_value_ok = lambda v: True
        self.log_value_callback = lambda v: 0

    def set_get_value_callback(self, lambda_get_value):
        """
        Changes callback to do value updates
        :param lambda_get_value: callback() returns: new value
        """
        self.lambda_get_value = lambda_get_value

    def set_value_validator(self, lambda_is_value_ok):
        """
        Changes callback to check if given value is valid.
        :param lambda_is_value_ok: callback(value) returns: bool
        """
        self.lambda_is_value_ok = lambda_is_value_ok

    def set_log_value_callback(self, log_value_callback):
        """
        Changes callback to log new values into some user's logger.
        :param log_value_callback: callback(value): void
        """
        self.log_value_callback = log_value_callback

    def execute_work(self):
        """
        Tries to updates values until get valid value.
        :return: value, success:bool
        """
        self._expect_get_value_callback()
        end_time = time.time() + float(self.timeout)
        while end_time >= time.time():
            next_sleep_time = time.time() + self.refresh_time
            value = self.lambda_get_value()
            # self.logger.info(msg_tmp.format(value))
            self.log_value_callback(value)
            if self.lambda_is_value_ok(value):
                return value, True
            else:
                next_sleep_time -= time.time()
                if next_sleep_time > 0:
                    time.sleep(next_sleep_time)
        return value, False

    def _expect_get_value_callback(self):
        if self.lambda_get_value is None:
            raise SleepyLoopWorkerNoCallbackException("Please first run method set_get_value_callback")

    def is_already_achieved(self):
        """
        Tests if already wanted value is returing.
        :return: bool
        """
        self._expect_get_value_callback()
        value = self.lambda_get_value()
        return self.lambda_is_value_ok(value)


class SleepyLoopWorkerNoCallbackException(UeManagerException):
    """Thrown when sleepy loop worker doesn't receive callback function for get_value"""
    pass
